class Retangulo {
  constructor(largura, altura) {
    this.largura = largura;
    this.altura = altura;
  }

  area() {
    return this.largura * this.altura;
  }

  perimetro() {
    return 2 * (this.largura + this.altura);
  }
}

const r1 = new Retangulo(4, 5);
console.log(r1.area()); // 20
console.log(r1.perimetro()); // 18

class Animal {
  constructor(nome) {
    this.nome = nome;
  }

  apresentar() {
    return `Sou ${this.nome}.`;
  }
}

class Cao extends Animal {
  constructor(nome, raca) {
    super(nome); // obrigatório antes de usar "this"
    this.raca = raca;
  }

  ladrar() {
    return `${this.nome} diz: Woof!`;
  }
}

const rex = new Cao("Rex", "Labrador");
console.log(rex.apresentar()); // Sou Rex.
console.log(rex.ladrar()); // Rex diz: Woof!
console.log(rex instanceof Animal); // true

class Funcionario {
  constructor(nome, salarioBase) {
    this.nome = nome;
    this.salarioBase = salarioBase;
  }

  calcularSalario() {
    return this.salarioBase;
  }
}

class Gestor extends Funcionario {
  constructor(nome, salarioBase, bonus) {
    super(nome, salarioBase);
    this.bonus = bonus;
  }

  // sobrescreve o método herdado, reaproveitando o comportamento original
  calcularSalario() {
    return super.calcularSalario() + this.bonus;
  }
}

const ana = new Funcionario("Ana", 1500);
const bruno = new Gestor("Bruno", 1500, 400);

console.log(ana.calcularSalario()); // 1500
console.log(bruno.calcularSalario()); // 1900

class Utilizador {
  static contagem = 0; // propriedade estática

  constructor(nome) {
    this.nome = nome;
    Utilizador.contagem++;
  }

  static criarConvidado() {
    // método de fábrica: não precisa de uma instância existente
    return new Utilizador("Convidado");
  }

  static get totalCriados() {
    return Utilizador.contagem;
  }
}

const u1 = new Utilizador("Marta");
const u2 = Utilizador.criarConvidado();

console.log(Utilizador.totalCriados); // 2
console.log(u1.contagem); // undefined — não existe na instância

class Ponto {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }

  distanciaAOrigem() {
    return Math.sqrt(this.x ** 2 + this.y ** 2);
  }
}

console.log(typeof Ponto); // "function" — uma classe é uma função especial
console.log(Object.getPrototypeOf(new Ponto(3, 4)) === Ponto.prototype); // true
console.log(Ponto.prototype.hasOwnProperty("distanciaAOrigem")); // true

// O mesmo resultado, escrito ao estilo pré-ES6 com funções construtoras
function PontoAntigo(x, y) {
  this.x = x;
  this.y = y;
}

PontoAntigo.prototype.distanciaAOrigem = function () {
  return Math.sqrt(this.x ** 2 + this.y ** 2);
};

const p = new Ponto(3, 4);
const pAntigo = new PontoAntigo(3, 4);
console.log(p.distanciaAOrigem() === pAntigo.distanciaAOrigem()); // true

