class Veiculo {
  constructor(marca, velocidadeMaxima) {
    this.marca = marca;
    this.velocidadeMaxima = velocidadeMaxima;
  }

  descricao() {
    return `${this.marca}, até ${this.velocidadeMaxima} km/h`;
  }
}

class CarroDesportivo extends Veiculo {
  constructor(marca, velocidadeMaxima, modoTurbo) {
    super(marca, velocidadeMaxima);
    this.modoTurbo = modoTurbo;
  }

  descricao() {
    const base = super.descricao();
    return this.modoTurbo ? `${base} [turbo ativo]` : base;
  }
}

const c1 = new CarroDesportivo("Ferrari", 340, true);
const c2 = new CarroDesportivo("Fiat", 160, false);

console.log(c1.descricao()); // Ferrari, até 340 km/h [turbo ativo]
console.log(c2.descricao()); // Fiat, até 160 km/h

class ContaBancaria {
  static taxaJuro = 0.02;
  static numeroContasCriadas = 0;

  constructor(titular, saldoInicial) {
    this.titular = titular;
    this.saldo = saldoInicial;
    ContaBancaria.numeroContasCriadas++;
  }

  aplicarJuro() {
    this.saldo *= 1 + ContaBancaria.taxaJuro;
    return this.saldo;
  }

  static criarContaZero(titular) {
    return new ContaBancaria(titular, 0);
  }
}

const conta1 = new ContaBancaria("Marta", 1000);
const conta2 = new ContaBancaria("João", 500);
const conta3 = ContaBancaria.criarContaZero("Convidado");

conta1.aplicarJuro();

console.log(conta1.saldo); // 1020
console.log(conta3.saldo); // 0
console.log(ContaBancaria.numeroContasCriadas); // 3

class Forma {
  area() {
    return 0;
  }

  static compararAreas(formaA, formaB) {
    const areaA = formaA.area();
    const areaB = formaB.area();

    if (areaA === areaB) return "iguais";
    return areaA > areaB ? "primeira maior" : "segunda maior";
  }
}

class Circulo extends Forma {
  constructor(raio) {
    super();
    this.raio = raio;
  }

  area() {
    return Math.PI * this.raio ** 2;
  }
}

class Quadrado extends Forma {
  constructor(lado) {
    super();
    this.lado = lado;
  }

  area() {
    return this.lado ** 2;
  }
}

const circulo = new Circulo(2);
const quadrado = new Quadrado(3);

console.log(Forma.compararAreas(circulo, quadrado)); // primeira maior
console.log(Object.getPrototypeOf(Circulo.prototype) === Forma.prototype); // true
